const clockFormatters=new Map();
export function formatClock(now,timeZone){if(!clockFormatters.has(timeZone))clockFormatters.set(timeZone,new Intl.DateTimeFormat('en-GB',{timeZone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}));return clockFormatters.get(timeZone).format(now);}
export function isSceneReady(win,doc){return Boolean(win.__sceneReady||win.__seoulReady||win.littleWorld?.ready||doc.querySelector('#loading')?.classList.contains('done'));}
function mountWorldShell(){
 const configElement=document.querySelector('#world-shell-config');if(!configElement)return;const config=JSON.parse(configElement.textContent),loader=document.querySelector('#world-loading'),status=document.querySelector('#world-load-status'),actions=loader.querySelector('.world-load-actions'),clock=document.querySelector('#world-clock'),notes=document.querySelector('#world-notes'),entered=performance.now(),minimum=matchMedia('(prefers-reduced-motion: reduce)').matches?0:850;let finished=false,failed=false,slowTimer;
 function updateClock(){try{const now=new Date();clock.textContent=formatClock(now,config.zone);clock.dateTime=now.toISOString();clock.title=config.timeNote;}catch{clock.textContent='Clock unavailable';}}
 // Seoul originally had a standalone toolbar. Give every country the same
 // measured control region without replacing its engine or event handlers.
 const toolbar=document.querySelector('.toolbar');
 if(toolbar&&!toolbar.closest('.toolbar-wrap')){const wrap=document.createElement('div');wrap.className='toolbar-wrap';toolbar.before(wrap);wrap.append(toolbar);}
 if(toolbar){toolbar.setAttribute('role','toolbar');toolbar.setAttribute('aria-label','World controls');const count=[...toolbar.querySelectorAll('button')].filter(button=>!button.hidden).length;document.body.style.setProperty('--world-control-columns',String(count>5?Math.ceil(count/2):count));}
 const orbitIcon=toolbar?.querySelector('#orbit svg');if(orbitIcon)orbitIcon.innerHTML='<ellipse cx="12" cy="12" rx="10" ry="5" transform="rotate(-25 12 12)"/><circle cx="12" cy="12" r="2"/>';
 const motion=toolbar?.querySelector('#life, #pause');
 function motionUI(){if(!motion)return;const pressed=motion.getAttribute('aria-pressed')==='true',running=['germany','switzerland'].includes(config.id)?pressed:!pressed,label=motion.querySelector('span'),text=running?'Pause':'Play',svg=motion.querySelector('svg'),icon=running?'<path d="M8 5v14M16 5v14"/>':'<path d="m8 5 11 7-11 7Z"/>';if(label&&label.textContent!==text)label.textContent=text;if(svg&&svg.innerHTML!==icon)svg.innerHTML=icon;}
 if(motion){new MutationObserver(motionUI).observe(motion,{attributes:true,attributeFilter:['aria-pressed']});motionUI();}
 function theme(){const mode=document.body.dataset.time==='sunset'?'sunset':document.body.classList.contains('night')||document.body.dataset.time==='night'?'night':'day';document.body.dataset.shellTheme=mode;
  const day=document.querySelector('#day');if(day&&!day.hidden){const label=day.querySelector('span');if(label&&label.textContent!==(mode==='night'?'Night':'Day'))label.textContent=mode==='night'?'Night':'Day';day.setAttribute('aria-label',mode==='night'?'Switch to day':'Switch to night');const svg=day.querySelector('svg');if(svg)svg.innerHTML=mode==='night'?'<path d="M19.5 15.5A8 8 0 0 1 8.5 4.5 8 8 0 1 0 19.5 15.5Z"/>':'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>';}
 }
 function layout(){const controls=document.querySelector('.toolbar-wrap')||toolbar,title=document.querySelector('.title');if(controls){const box=controls.getBoundingClientRect(),beside=innerWidth>1100&&title&&title.getBoundingClientRect().right<box.left-24;document.body.style.setProperty('--world-title-bottom',`${beside?28:Math.ceil(innerHeight-box.top+20)}px`);}}
 function fail(message){if(finished||isSceneReady(window,document))return;failed=true;loader.classList.add('has-error');status.textContent=message||'The world could not load. Check your connection and try again.';actions.hidden=false;}
 function complete(){if(finished)return;finished=true;clearTimeout(slowTimer);loader.classList.add('is-done');document.body.dataset.worldReady='true';window.__worldShellReady=true;try{const visits=JSON.parse(localStorage.getItem('elsewhere-visits')||'[]');localStorage.setItem('elsewhere-visits',JSON.stringify([...new Set([...(Array.isArray(visits)?visits:[]),config.id])]));}catch{}setTimeout(()=>loader.remove(),550);layout();}
 function readiness(){if(finished)return;if(isSceneReady(window,document)&&performance.now()-entered>=minimum){complete();return;}if(failed)setTimeout(readiness,500);else requestAnimationFrame(readiness);}
 updateClock();theme();layout();setInterval(updateClock,15000);const observer=new MutationObserver(theme);observer.observe(document.body,{attributes:true,attributeFilter:['class','data-time']});const controls=document.querySelector('.toolbar-wrap')||document.querySelector('.toolbar');if(controls&&typeof ResizeObserver!=='undefined')new ResizeObserver(layout).observe(controls);addEventListener('resize',layout);addEventListener('pageshow',()=>{updateClock();theme();layout();});document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateClock();});
 addEventListener('error',event=>{if(event.message)fail('The world could not load. Please check your connection and reload.');});addEventListener('unhandledrejection',()=>fail('The world could not load. Please check your connection and reload.'));
 slowTimer=setTimeout(()=>{if(!finished&&!failed){status.textContent='Still loading the 3D engine. Check your connection if this takes too long.';actions.hidden=false;}},18000);window.__worldShellStarted=true;requestAnimationFrame(readiness);
 document.addEventListener('pointerdown',event=>{if(notes.open&&!notes.contains(event.target))notes.open=false;});document.addEventListener('keydown',event=>{if(event.key==='Escape')notes.open=false;});
}
if(typeof document!=='undefined')mountWorldShell();
